// GraphQL Client for HomeCook Platform
// Handles queries and mutations for food data

interface FoodItem {
  id: string
  name: string
  description: string
  price: number
  calories: number
  image: string
  cookName: string
  rating: number
  prepTime: string
  ingredients: string[]
  customizations: Customization[]
  available: boolean
  category: string
}

interface Customization {
  id: string
  name: string
  type: 'select' | 'checkbox' | 'radio'
  options: CustomizationOption[]
  required: boolean
}

interface CustomizationOption {
  id: string
  name: string
  price: number
}

interface GraphQLResponse<T> {
  data?: T
  errors?: Array<{ message: string }>
}

