// Simulate GraphQL query with delay
const simulateNetworkDelay = () => new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400))

export async function fetchFoodItems(): Promise<FoodItem[]> {
  try {
    await simulateNetworkDelay()
    
    // Simulate occasional network errors for testing
    if (Math.random() < 0.05) {
      throw new Error('Network error')
    }
    
    return mockFoodItems.filter(item => item.available)
  } catch (error) {
    console.error('Error fetching food items:', error)
    throw new Error('Failed to fetch food items')
  }
}

export async function fetchFoodItemById(id: string): Promise<FoodItem | null> {
  try {
    await simulateNetworkDelay()
    
    const item = mockFoodItems.find(item => item.id === id && item.available)
    return item || null
  } catch (error) {
    console.error('Error fetching food item:', error)
    throw new Error('Failed to fetch food item')
  }
}

export async function searchFoodItems(query: string, category?: string): Promise<FoodItem[]> {
  try {
    await simulateNetworkDelay()
    
    let filtered = mockFoodItems.filter(item => item.available)
    
    if (query) {
      const searchTerm = query.toLowerCase()
      filtered = filtered.filter(item => 
        item.name.toLowerCase().includes(searchTerm) ||
        item.description.toLowerCase().includes(searchTerm) ||
        item.cookName.toLowerCase().includes(searchTerm) ||
        item.ingredients.some(ingredient => ingredient.toLowerCase().includes(searchTerm))
      )
    }
    
    if (category) {
      filtered = filtered.filter(item => item.category === category)
    }
    
    return filtered
  } catch (error) {
    console.error('Error searching food items:', error)
    throw new Error('Failed to search food items')
  }
}

// GraphQL mutation for creating new food items (for cooks)
export async function createFoodItem(foodData: Omit<FoodItem, 'id' | 'rating'>): Promise<FoodItem> {
  try {
    await simulateNetworkDelay()
    
    const newItem: FoodItem = {
      ...foodData,
      id: Date.now().toString(),
      rating: 0
    }
    
    // In a real implementation, this would send to GraphQL endpoint
    mockFoodItems.push(newItem)
    
    return newItem
  } catch (error) {
    console.error('Error creating food item:', error)
    throw new Error('Failed to create food item')
  }
}

// GraphQL query for getting categories
export async function getFoodCategories(): Promise<string[]> {
  try {
    await simulateNetworkDelay()
    
    const categories = [...new Set(mockFoodItems.map(item => item.category))]
    return categories.sort()
  } catch (error) {
    console.error('Error fetching categories:', error)
    throw new Error('Failed to fetch categories')
  }
}

// Helper function to make actual GraphQL requests (for future implementation)
async function makeGraphQLRequest<T>(query: string, variables?: Record<string, any>): Promise<GraphQLResponse<T>> {
  const response = await fetch('/api/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      query,
      variables,
    }),
  })

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`)
  }

  return response.json()
}

export type { FoodItem, Customization, CustomizationOption }
