"use client"

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import NavigationBar from '@/components/navigation/NavigationBar'
import FoodDetails from '@/components/food/FoodDetails'
import CustomizationForm from '@/components/food/CustomizationForm'
import { fetchFoodItemById, type FoodItem } from '@/lib/graphqlClient'

export default function FoodDetailsPage() {
  const params = useParams()
  const router = useRouter()
  const [foodItem, setFoodItem] = useState<FoodItem | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const loadFoodItem = async () => {
      try {
        const id = params.id as string
        const item = await fetchFoodItemById(id)
        
        if (!item) {
          setError('Food item not found')
          return
        }
        
        setFoodItem(item)
      } catch (err) {
        setError('Failed to load food item. Please try again later.')
        console.error('Error loading food item:', err)
      } finally {
        setLoading(false)
      }
    }

    if (params.id) {
      loadFoodItem()
    }
  }, [params.id])

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <NavigationBar />
        <div className="container mx-auto px-4 py-8">
          <div className="max-w-4xl mx-auto">
            <div className="animate-pulse">
              <div className="h-8 bg-gray-200 rounded w-1/4 mb-6"></div>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="h-96 bg-gray-200 rounded-lg"></div>
                <div className="space-y-4">
                  <div className="h-8 bg-gray-200 rounded w-3/4"></div>
                  <div className="h-4 bg-gray-200 rounded w-1/2"></div>
                  <div className="h-20 bg-gray-200 rounded"></div>
                  <div className="h-32 bg-gray-200 rounded"></div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  if (error || !foodItem) {
    return (
      <div className="min-h-screen bg-gray-50">
        <NavigationBar />
        <div className="container mx-auto px-4 py-8">
          <div className="max-w-2xl mx-auto text-center py-12">
            <h2 className="text-2xl font-semibold text-gray-900 mb-4">
              {error || 'Food item not found'}
            </h2>
            <p className="text-gray-600 mb-6">
              The food item you're looking for might have been removed or is temporarily unavailable.
            </p>
            <div className="flex gap-4 justify-center">
              <button 
                onClick={() => router.back()}
                className="bg-gray-200 text-gray-800 px-6 py-3 rounded-lg hover:bg-gray-300 transition-colors"
              >
                Go Back
              </button>
              <button 
                onClick={() => router.push('/')}
                className="bg-black text-white px-6 py-3 rounded-lg hover:bg-gray-800 transition-colors"
              >
                Browse All Meals
              </button>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <NavigationBar />
      
      <div className="container mx-auto px-4 py-8">
        {/* Breadcrumb */}
        <nav className="mb-6">
          <button 
            onClick={() => router.back()}
            className="text-gray-600 hover:text-gray-900 transition-colors flex items-center gap-2"
          >
            <span>←</span> Back to meals
          </button>
        </nav>

        <div className="max-w-6xl mx-auto">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
            {/* Food Details */}
            <FoodDetails food={foodItem} />
            
            {/* Customization Form */}
            <div className="lg:sticky lg:top-24 lg:self-start">
              <CustomizationForm food={foodItem} />
            </div>
          </div>

          {/* Additional Information */}
          <div className="bg-white rounded-lg shadow-sm border p-6">
            <h3 className="text-xl font-semibold text-gray-900 mb-4">About the Cook</h3>
            <div className="flex items-start gap-4">
              <div className="w-16 h-16 bg-gray-200 rounded-full flex items-center justify-center">
                <span className="text-2xl">👨‍🍳</span>
              </div>
              <div>
                <h4 className="font-medium text-gray-900">{foodItem.cookName}</h4>
                <p className="text-gray-600 text-sm mb-2">Home Cook</p>
                <p className="text-gray-700 text-sm">
                  Passionate about creating authentic, home-style meals using traditional recipes 
                  and fresh, locally-sourced ingredients. Every dish is prepared with love and care.
                </p>
                <div className="flex items-center gap-4 mt-3 text-sm text-gray-600">
                  <span>⭐ {foodItem.rating.toFixed(1)} rating</span>
                  <span>🕒 Usually ready in {foodItem.prepTime}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
