"use client"

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { type FoodItem, type Customization, type CustomizationOption } from '@/lib/graphqlClient'

interface CustomizationFormProps {
  food: FoodItem
}

interface CartItem {
  foodId: string
  foodName: string
  basePrice: number
  customizations: Record<string, string | string[]>
  totalPrice: number
  quantity: number
}

export default function CustomizationForm({ food }: CustomizationFormProps) {
  const router = useRouter()
  const [selectedOptions, setSelectedOptions] = useState<Record<string, string | string[]>>({})
  const [quantity, setQuantity] = useState(1)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [isAddingToCart, setIsAddingToCart] = useState(false)

  // Calculate total price based on selected options
  const calculateTotalPrice = () => {
    let total = food.price * quantity
    
    food.customizations.forEach(customization => {
      const selected = selectedOptions[customization.id]
      
      if (customization.type === 'checkbox' && Array.isArray(selected)) {
        selected.forEach(optionId => {
          const option = customization.options.find(opt => opt.id === optionId)
          if (option) total += option.price * quantity
        })
      } else if (typeof selected === 'string') {
        const option = customization.options.find(opt => opt.id === selected)
        if (option) total += option.price * quantity
      }
    })
    
    return total
  }

  // Handle option selection
  const handleOptionChange = (customizationId: string, optionId: string, type: string) => {
    setSelectedOptions(prev => {
      const newOptions = { ...prev }
      
      if (type === 'checkbox') {
        const currentSelection = Array.isArray(newOptions[customizationId]) 
          ? newOptions[customizationId] as string[]
          : []
        
        if (currentSelection.includes(optionId)) {
          newOptions[customizationId] = currentSelection.filter(id => id !== optionId)
        } else {
          newOptions[customizationId] = [...currentSelection, optionId]
        }
      } else {
        newOptions[customizationId] = optionId
      }
      
      return newOptions
    })
    
    // Clear error for this customization
    if (errors[customizationId]) {
      setErrors(prev => {
        const newErrors = { ...prev }
        delete newErrors[customizationId]
        return newErrors
      })
    }
  }

  // Validate required customizations
  const validateForm = () => {
    const newErrors: Record<string, string> = {}
    
    food.customizations.forEach(customization => {
      if (customization.required) {
        const selected = selectedOptions[customization.id]
        
        if (!selected || 
            (Array.isArray(selected) && selected.length === 0) ||
            (typeof selected === 'string' && !selected)) {
          newErrors[customization.id] = `Please select ${customization.name.toLowerCase()}`
        }
      }
    })
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Add to cart
  const handleAddToCart = async () => {
    if (!validateForm()) return
    
    setIsAddingToCart(true)
    
    try {
      const cartItem: CartItem = {
        foodId: food.id,
        foodName: food.name,
        basePrice: food.price,
        customizations: selectedOptions,
        totalPrice: calculateTotalPrice(),
        quantity
      }
      
      // Simulate adding to cart (in real app, this would call an API)
      await new Promise(resolve => setTimeout(resolve, 500))
      
      // Store in localStorage for now (in real app, this would be in a cart context/state)
      const existingCart = JSON.parse(localStorage.getItem('cart') || '[]')
      existingCart.push(cartItem)
      localStorage.setItem('cart', JSON.stringify(existingCart))
      
      // Show success message and redirect
      alert('Added to cart successfully!')
      router.push('/checkout')
      
    } catch (error) {
      console.error('Error adding to cart:', error)
      alert('Failed to add to cart. Please try again.')
    } finally {
      setIsAddingToCart(false)
    }
  }

  const totalPrice = calculateTotalPrice()

  return (
    <div className="bg-white rounded-lg shadow-sm border p-6 space-y-6">
      {/* Price Header */}
      <div className="border-b pb-4">
        <div className="flex items-center justify-between">
          <div>
            <span className="text-3xl font-bold text-gray-900">${totalPrice.toFixed(2)}</span>
            {totalPrice !== food.price * quantity && (
              <span className="text-sm text-gray-500 ml-2">
                (Base: ${(food.price * quantity).toFixed(2)})
              </span>
            )}
          </div>
          <div className="text-right">
            <div className="text-sm text-gray-600">per serving</div>
            <div className="text-sm text-gray-500">{food.calories} calories</div>
          </div>
        </div>
      </div>

      {/* Quantity Selector */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Quantity
        </label>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setQuantity(Math.max(1, quantity - 1))}
            className="w-10 h-10 border border-gray-300 rounded-lg flex items-center justify-center hover:bg-gray-50 transition-colors"
            disabled={quantity <= 1}
          >
            -
          </button>
          <span className="text-lg font-medium w-8 text-center">{quantity}</span>
          <button
            onClick={() => setQuantity(quantity + 1)}
            className="w-10 h-10 border border-gray-300 rounded-lg flex items-center justify-center hover:bg-gray-50 transition-colors"
          >
            +
          </button>
        </div>
      </div>

      {/* Customizations */}
      {food.customizations.map((customization) => (
        <div key={customization.id} className="space-y-3">
          <label className="block text-sm font-medium text-gray-700">
            {customization.name}
            {customization.required && <span className="text-red-500 ml-1">*</span>}
          </label>
          
          {errors[customization.id] && (
            <p className="text-sm text-red-600">{errors[customization.id]}</p>
          )}
          
          <div className="space-y-2">
            {customization.options.map((option) => {
              const isSelected = customization.type === 'checkbox'
                ? Array.isArray(selectedOptions[customization.id]) && 
                  (selectedOptions[customization.id] as string[]).includes(option.id)
                : selectedOptions[customization.id] === option.id
              
              return (
                <label
                  key={option.id}
                  className={`flex items-center justify-between p-3 border rounded-lg cursor-pointer transition-colors ${
                    isSelected 
                      ? 'border-gray-900 bg-gray-50' 
                      : 'border-gray-200 hover:border-gray-300'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <input
                      type={customization.type === 'checkbox' ? 'checkbox' : 'radio'}
                      name={customization.id}
                      value={option.id}
                      checked={isSelected}
                      onChange={() => handleOptionChange(customization.id, option.id, customization.type)}
                      className="w-4 h-4"
                    />
                    <span className="text-sm text-gray-900">{option.name}</span>
                  </div>
                  
                  {option.price !== 0 && (
                    <span className={`text-sm ${option.price > 0 ? 'text-gray-600' : 'text-green-600'}`}>
                      {option.price > 0 ? '+' : ''}${option.price.toFixed(2)}
                    </span>
                  )}
                </label>
              )
            })}
          </div>
        </div>
      ))}

      {/* Special Instructions */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Special Instructions (Optional)
        </label>
        <textarea
          placeholder="Any special requests or dietary restrictions..."
          className="w-full p-3 border border-gray-300 rounded-lg resize-none focus:ring-2 focus:ring-gray-900 focus:border-transparent"
          rows={3}
        />
      </div>

      {/* Add to Cart Button */}
      <button
        onClick={handleAddToCart}
        disabled={isAddingToCart}
        className={`w-full py-4 px-6 rounded-lg font-medium transition-colors ${
          isAddingToCart
            ? 'bg-gray-400 text-white cursor-not-allowed'
            : 'bg-gray-900 text-white hover:bg-gray-800'
        }`}
      >
        {isAddingToCart ? 'Adding to Cart...' : `Add to Cart • $${totalPrice.toFixed(2)}`}
      </button>

      {/* Delivery Info */}
      <div className="bg-gray-50 rounded-lg p-4 text-sm text-gray-600">
        <div className="flex items-center gap-2 mb-2">
          <span>🚚</span>
          <span className="font-medium">Delivery Information</span>
        </div>
        <ul className="space-y-1 text-xs">
          <li>• Estimated delivery: 30-45 minutes</li>
          <li>• Delivery fee: $2.99 (free over $25)</li>
          <li>• Freshly prepared when you order</li>
        </ul>
      </div>
    </div>
  )
}
