"use client"

import { useState } from 'react'
import { type FoodItem } from '@/lib/graphqlClient'

interface FoodDetailsProps {
  food: FoodItem
}

export default function FoodDetails({ food }: FoodDetailsProps) {
  const [imageError, setImageError] = useState(false)
  const [showAllIngredients, setShowAllIngredients] = useState(false)

  const displayedIngredients = showAllIngredients 
    ? food.ingredients 
    : food.ingredients.slice(0, 6)

  return (
    <div className="space-y-6">
      {/* Main Image */}
      <div className="relative h-96 overflow-hidden rounded-lg bg-gray-100">
        {!imageError ? (
          <img
            src={food.image}
            alt={food.name}
            className="w-full h-full object-cover"
            onError={() => setImageError(true)}
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center bg-gray-100">
            <div className="text-center">
              <div className="w-24 h-24 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-4xl">🍽️</span>
              </div>
              <p className="text-gray-500">Image not available</p>
            </div>
          </div>
        )}
        
        {/* Overlay Info */}
        <div className="absolute bottom-4 left-4 right-4">
          <div className="bg-white/90 backdrop-blur-sm rounded-lg p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4 text-sm">
                <span className="flex items-center gap-1">
                  ⭐ {food.rating.toFixed(1)}
                </span>
                <span className="flex items-center gap-1">
                  🕒 {food.prepTime}
                </span>
                <span className="flex items-center gap-1">
                  🔥 {food.calories} cal
                </span>
              </div>
              <span className="bg-black text-white px-2 py-1 rounded text-sm">
                {food.category}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Title and Description */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900 mb-2">{food.name}</h1>
        <p className="text-gray-600 text-lg leading-relaxed">{food.description}</p>
      </div>

      {/* Cook Info */}
      <div className="bg-gray-50 rounded-lg p-4">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
            <span className="text-xl">👨‍🍳</span>
          </div>
          <div>
            <p className="font-medium text-gray-900">Prepared by {food.cookName}</p>
            <p className="text-sm text-gray-600">Home Cook • {food.category} Cuisine</p>
          </div>
        </div>
      </div>

      {/* Ingredients */}
      <div className="bg-white rounded-lg border p-6">
        <h3 className="text-xl font-semibold text-gray-900 mb-4">Ingredients</h3>
        <div className="grid grid-cols-2 gap-2">
          {displayedIngredients.map((ingredient, index) => (
            <div key={index} className="flex items-center gap-2 text-sm text-gray-700">
              <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
              {ingredient}
            </div>
          ))}
        </div>
        
        {food.ingredients.length > 6 && (
          <button
            onClick={() => setShowAllIngredients(!showAllIngredients)}
            className="mt-3 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAllIngredients 
              ? 'Show less' 
              : `Show ${food.ingredients.length - 6} more ingredients`
            }
          </button>
        )}
      </div>

      {/* Nutritional Info */}
      <div className="bg-white rounded-lg border p-6">
        <h3 className="text-xl font-semibold text-gray-900 mb-4">Nutritional Information</h3>
        <div className="grid grid-cols-2 gap-4">
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <div className="text-2xl font-bold text-gray-900">{food.calories}</div>
            <div className="text-sm text-gray-600">Calories</div>
          </div>
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <div className="text-2xl font-bold text-gray-900">{food.prepTime}</div>
            <div className="text-sm text-gray-600">Prep Time</div>
          </div>
        </div>
        
        <div className="mt-4 p-4 bg-blue-50 rounded-lg">
          <p className="text-sm text-blue-800">
            <strong>Note:</strong> Nutritional values are estimates based on standard ingredients. 
            Actual values may vary depending on specific brands and preparation methods used by the cook.
          </p>
        </div>
      </div>

      {/* Dietary Information */}
      <div className="bg-white rounded-lg border p-6">
        <h3 className="text-xl font-semibold text-gray-900 mb-4">Dietary Information</h3>
        <div className="flex flex-wrap gap-2">
          {/* Mock dietary tags - in real app, these would come from the food data */}
          <span className="px-3 py-1 bg-green-100 text-green-800 text-sm rounded-full">
            Fresh Ingredients
          </span>
          <span className="px-3 py-1 bg-blue-100 text-blue-800 text-sm rounded-full">
            Home-Cooked
          </span>
          <span className="px-3 py-1 bg-purple-100 text-purple-800 text-sm rounded-full">
            Traditional Recipe
          </span>
        </div>
        
        <div className="mt-4 text-sm text-gray-600">
          <p>
            Please inform the cook of any allergies or dietary restrictions when placing your order. 
            All meals are prepared in home kitchens and may contain traces of common allergens.
          </p>
        </div>
      </div>
    </div>
  )
}
